#!/bin/bash
# This file was generated by Cursor AI on 2026-11-17.
#
# Prove MLTL rewrite rules via SMT:
#   rewrites.json -> equiv -> smt2 -> prove
#
# Usage: ./prove_rewrites.sh [timeout_seconds] [portfolio_jobs]

set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
COMPILER_DIR=$(cd "$SCRIPT_DIR/../.." && pwd)

TIMEOUT_SECONDS="${1:-60}"
PORTFOLIO_JOBS="${2:-8}"
C2PO_SCRIPT="$COMPILER_DIR/c2po.py"

cd "$SCRIPT_DIR"

echo "==> Generating .equiv files"
python3 "$SCRIPT_DIR/generate_equiv_files.py" rewrites.json equiv/

echo "==> Generating SMT2 encodings"
"$SCRIPT_DIR/generate_smt2_equiv.sh" equiv/ smt2/ "$C2PO_SCRIPT"

echo "==> Proving rewrite correctness (timeout=${TIMEOUT_SECONDS}s, jobs=${PORTFOLIO_JOBS})"
"$SCRIPT_DIR/prove.sh" smt2/ "$TIMEOUT_SECONDS" "$PORTFOLIO_JOBS"

echo "==> Prove complete"
echo "    smt2: $SCRIPT_DIR/smt2/"
